const DEBUGLAYERS = q.get("debugLayers")==="1";   // &debugLayers=1 → live read-out of every sky/cloud layer opacity
const DEBUGMOON = q.get("debugMoon")==="1";       // &debugMoon=1 → moon layer radii/opacities + a pixel-ring across the limb
const DEBUGDAWN = q.get("debugDawn");             // DEPRECATED no-op: dawn is not a painted overlay anymore (true dawn = the physical twilight sky + Fajr marker; false dawn is not rendered). Kept only so old URLs don't error.
const DEBUGOPTIC = q.get("debugOptic");           // &debugOptic=halo|sundogs|pillar|anticrep|paraselene|lunarhalo → force the corresponding QA branch; lunar forces retain moonlight eligibility
const QA = q.get("qa")==="1";                     // &qa=1 → reset lastWxAt/lastWxTry on boot; window.qaState() is always assigned
const DEBUGMOTION = q.get("debugMotion")==="1";   // &debugMotion=1 → live motion telemetry overlay (rAF & cloud-paint rates, reduced-motion, paused, cloud/star Δ over 10s/60s, wx source, timeScale, reason)
const MOTIONFULL = (q.get("motion")||"")==="full";// &motion=full → force full animation even under OS prefers-reduced-motion. DEFAULT respects accessibility (motion reduced when the OS asks), but this gives an honest override for testing and for users who want it
// SINGLE SOURCE for the reduced-motion decision (was duplicated as _REDUCED + _RM). Evaluated LIVE so a mid-session
// OS toggle is honoured (matchMedia is cheap); &motion=full overrides. The CSS @media (prefers-reduced-motion) blocks
// read the SAME native signal, gated by the .motionfull opt-out class — one decision, consulted by both JS and CSS.
const isMotionReduced = () => !MOTIONFULL && !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);

const _RAFNOW = ()=> (typeof performance!=='undefined' && performance.now) ? performance.now() : Date.now();
const _tsParam=q.get("timeScale");
let TIMESCALE = _tsParam!=null ? Math.max(0,+_tsParam||0) : (SIM.time!=null ? 0 : 1);
let ADVANCING = _tsParam!=null && TIMESCALE>0;          // a running fast-forward → show the sim clock
let FOLLOW_WALL_CLOCK = _tsParam==null && SIM.time==null && TIMESCALE===1;
let _clockPreview=false; // explicit runtime clock control retains forecast provenance while paused

function updateMotionDbg(rafPS, cloudPS, cEl){
  const dm=document.querySelector('.dbgmotion'); if(!dm) return; if(dm.style.display!=='block') dm.style.display='block';
  _motHist.push({a:_cloudAlphaNow(), s:_starSampleNow()}); if(_motHist.length>61)_motHist.shift();
  const cur=_motHist[_motHist.length-1], h10=_motHist[Math.max(0,_motHist.length-11)], h60=_motHist[0];
  const pct=(a,b)=> b? (Math.abs(a-b)/b*100):0;
  const starAnim=(()=>{ const e=document.querySelector('.stars circle'); return e?getComputedStyle(e).animationName==='tw':false; })();
  const wt=(()=>{try{return qaState().wxTruth;}catch(e){return {};}})(); const rm=isMotionReduced();   // LIVE (honours a mid-session OS toggle)
  dm.textContent=`MOTION rAF ${rafPS}/s  cloudPaint ${cloudPS}/s\n`
    +`reduced ${rm?'YES':'no'}  motion=full ${MOTIONFULL?'YES':'no'}  paused ${cEl.classList.contains('paused')?'YES':'no'}\n`
    +`timeScale ${TIMESCALE}  advancing ${ADVANCING?'yes':'no'}\n`
    +`cloudΔ 10s ${pct(cur.a,h10&&h10.a).toFixed(1)}%  60s ${pct(cur.a,h60&&h60.a).toFixed(1)}%\n`
    +`starΔ 10s ${(cur.s-(h10?h10.s:cur.s)).toFixed(3)}  starAnim ${starAnim?'on':'OFF'}\n`
    +`wx ${wt.currentWeatherSource||'?'}  fx ${cEl.dataset.fx||'?'}\n`
    +`reason ${rm?'OS reduced-motion (add motion=full to override)':(cEl.classList.contains('paused')?'offscreen/hidden → paused (battery)':'full real-time motion')}`;
}

function startRenderLoop(){
  if(!simulationReady()) return;
  if(_loopStarted) return; _loopStarted=true;
  const cEl=document.querySelector(".c");
  if(MOTIONFULL && cEl) cEl.classList.add("motionfull");    // CSS reduced-motion rules are scoped to .c:not(.motionfull)
  let _raf=null, _onScreen=true, _lastSec=-1, _lastWx=0, _lastCloud=0;
  const visible=()=>_onScreen && document.visibilityState!=="hidden";
  // —— MOTION TELEMETRY (&debugMotion=1): prove the sky is actually alive in normal real-time ——
  let _rafN=0,_cloudN=0,_tickAcc=_RAFNOW(),_rafPS=0,_cloudPS=0;   // loop rate counters (consumed only by the debugMotion overlay, which now lives at module scope)
  function loop(){
    _rafN++;
    if(!simulationReady()){ _raf=requestAnimationFrame(loop); return; }
    const n=nowParts();
    maintainPrayerDay();                               // promotion, rollover and cold same-day recovery share this visible opportunity
    const rt=_RAFNOW();
    if(!ADVANCING && rt-_lastWx>30000){ _lastWx=rt; fetchWeather(); fetchRadar(); }    // refresh real weather ~½-min + radar (self-throttled ~10min); both held during a fast sweep
    const sec=Math.floor(simNow()/1000);
    if(sec!==_lastSec || _renderDirty){ _lastSec=sec; _renderDirty=false; render(); if(ADVANCING) updateSimClock(n); }
    // Cloud evolution uses bounded visual intervals, with CLOCK's preview rate. Reduced-motion
    // paints changed state at the same held axes, never a substitute epoch like 1000.
    const reduced=isMotionReduced(); syncCloudMotionPreference(reduced,rt);
    if(reduced){ if(_cloudDirty){ paintClouds(simNow()/1000); tieRainToClouds(); _cloudN++; } }
    else if(rt-_lastCloud>76){ _lastCloud=rt; paintClouds(simNow()/1000); tieRainToClouds(); _cloudN++; }
    if(rt-_tickAcc>=1000){ _rafPS=Math.round(_rafN*1000/(rt-_tickAcc)); _cloudPS=Math.round(_cloudN*1000/(rt-_tickAcc)); _rafN=0;_cloudN=0;_tickAcc=rt; if(DEBUGMOTION) updateMotionDbg(_rafPS,_cloudPS,cEl); }
    // Optional sky presents after native UI/cloud work, using a freshly
    // accepted UTC. Bootstrap owns its own callback until this handoff.
    window.SalahSkyPreview?.present(_RAFNOW());
    _raf=requestAnimationFrame(loop);
  }
  function start(){ if(!_raf) _raf=requestAnimationFrame(loop); }
  function stop(){ if(_raf){ cancelAnimationFrame(_raf); _raf=null; } }
  function setVis(){ const on=visible(); rebaseCloudMotion(!on); if(cEl){ cEl.classList.toggle("paused",!on); if(ADVANCING) cEl.classList.add("fast"); } if(on) start(); else stop(); }
  document.addEventListener("visibilitychange",setVis);
  if("IntersectionObserver" in window && cEl)
    new IntersectionObserver(es=>{ _onScreen=es[0].isIntersecting; setVis(); },{threshold:0}).observe(cEl);
  if(ADVANCING){ const sc=document.querySelector(".simclock"); if(sc) sc.style.display="block"; }
  setVis();
}

function simulationReady(){
  const valid=SIM.time==null || Number.isFinite(simNow()), sc=$(".simclock");
  if(!valid){
    for(const selector of [".sky","#wxfx",".climate",".arc",".bar",".cn",".times",".d"]){
      const el=$(selector); if(el && !_simHidden.has(el)){ _simHidden.set(el,el.style.visibility); el.style.visibility="hidden"; }
    }
    showError("Simulation time unavailable");
    if(sc){ if(_simClockDisplay===null) _simClockDisplay=sc.style.display; sc.textContent="SIM unavailable"; sc.style.display="block"; }
    return false;
  }
  for(const [el,visibility] of _simHidden) el.style.visibility=visibility;
  _simHidden.clear();
  if(sc && _simClockDisplay!==null){ sc.style.display=_simClockDisplay; _simClockDisplay=null; }
  return true;
}

function _starSampleNow(){ const els=document.querySelectorAll('.stars circle'); for(const e of els){ if(e.style.display!=='none' && getComputedStyle(e).animationName==='tw') return +getComputedStyle(e).opacity; } return 0; }   // sample a VISIBLE twinkling star (not a display:none pool star) so starΔ is representative
function updateMotionDbg(rafPS, cloudPS, cEl){
  const dm=document.querySelector('.dbgmotion'); if(!dm) return; if(dm.style.display!=='block') dm.style.display='block';
  _motHist.push({a:_cloudAlphaNow(), s:_starSampleNow()}); if(_motHist.length>61)_motHist.shift();
  const cur=_motHist[_motHist.length-1], h10=_motHist[Math.max(0,_motHist.length-11)], h60=_motHist[0];
  const pct=(a,b)=> b? (Math.abs(a-b)/b*100):0;
  const starAnim=(()=>{ const e=document.querySelector('.stars circle'); return e?getComputedStyle(e).animationName==='tw':false; })();
  const wt=(()=>{try{return qaState().wxTruth;}catch(e){return {};}})(); const rm=isMotionReduced();   // LIVE (honours a mid-session OS toggle)
  dm.textContent=`MOTION rAF ${rafPS}/s  cloudPaint ${cloudPS}/s\n`
    +`reduced ${rm?'YES':'no'}  motion=full ${MOTIONFULL?'YES':'no'}  paused ${cEl.classList.contains('paused')?'YES':'no'}\n`
    +`timeScale ${TIMESCALE}  advancing ${ADVANCING?'yes':'no'}\n`
    +`cloudΔ 10s ${pct(cur.a,h10&&h10.a).toFixed(1)}%  60s ${pct(cur.a,h60&&h60.a).toFixed(1)}%\n`
    +`starΔ 10s ${(cur.s-(h10?h10.s:cur.s)).toFixed(3)}  starAnim ${starAnim?'on':'OFF'}\n`
    +`wx ${wt.currentWeatherSource||'?'}  fx ${cEl.dataset.fx||'?'}\n`
    +`reason ${rm?'OS reduced-motion (add motion=full to override)':(cEl.classList.contains('paused')?'offscreen/hidden → paused (battery)':'full real-time motion')}`;
}

function simNow(){
  if(FOLLOW_WALL_CLOCK) return Date.now();
  if(!_simValid && _simInvalidTz===tz) return NaN;
  if((_simBase==null || _simTz!==tz) && !initSim()) return NaN;
  return _simBase + (_RAFNOW()-_rafT0)*TIMESCALE;
}
